function languageForPath(path) {
  const lower = String(path || "").toLowerCase();
  const name = lower.split(/[\\/]/).pop() || "";
  if (name === "dockerfile") return "dockerfile";
  if (name === "makefile") return "makefile";
  const extension = name.includes(".") ? name.slice(name.lastIndexOf(".")) : "";
  return {
    ".py": "python",
    ".pyw": "python",
    ".js": "javascript",
    ".mjs": "javascript",
    ".cjs": "javascript",
    ".jsx": "javascript",
    ".ts": "typescript",
    ".tsx": "typescript",
    ".json": "json",
    ".css": "css",
    ".scss": "scss",
    ".less": "less",
    ".html": "html",
    ".htm": "html",
    ".md": "markdown",
    ".markdown": "markdown",
    ".c": "c",
    ".h": "c",
    ".cpp": "cpp",
    ".hpp": "cpp",
    ".cc": "cpp",
    ".java": "java",
    ".xml": "xml",
    ".yml": "yaml",
    ".yaml": "yaml",
    ".sql": "sql",
    ".sh": "shell",
    ".bat": "bat",
    ".ps1": "powershell",
    ".ini": "ini",
    ".toml": "ini",
    ".go": "go",
    ".rs": "rust"
  }[extension] || "plaintext";
}
function modelUri(deviceId, path) {
  const device = encodeURIComponent(String(deviceId || "unknown"));
  const normalized = String(path || "untitled.txt").replace(/\\/g, "/").replace(/^\/+/, "");
  return Uri2.parse(`tether://${device}/${normalized}`);
}
function preferredTheme() {
  if (typeof document === "undefined") return "tether-light";
  const dark = !!(document.body && document.body.hasAttribute("data-ds-dark-theme")) || !!(document.documentElement && document.documentElement.hasAttribute("data-ds-dark-theme"));
  return dark ? "tether-dark" : "tether-light";
}
